dtsPropsFor.Badge:
/**
 * Colour is paired with text, always — a lone hue carries no meaning for a
 * colour-blind reader or anyone skimming a dense grid.
 */
tone?: "neutral" | "ok" | "warn" | "danger" | "info" | "accent";
children?: React.ReactNode;
className?: string;
/** Every other `<span>` attribute is spread onto the element. */

dtsPropsFor.Button:
/** Four intents, enumerated here so a "sort of primary" cannot come into existence. */
variant?: "primary" | "secondary" | "ghost" | "danger";
size?: "sm" | "md" | "lg" | "icon";
children?: React.ReactNode;
className?: string;
disabled?: boolean;
type?: "button" | "submit" | "reset";
onClick?: React.MouseEventHandler<HTMLButtonElement>;
/** Every other `<button>` attribute is spread onto the element. */
/** A navigation is an anchor, not a button — wear `buttonClass(...)` on an `<a>` instead. */

dtsPropsFor.DialogContent:
/**
 * Renders inside `<Dialog>` (the Radix root, also exported) — on its own it
 * mounts nothing. `<DialogTrigger>` opens it, `<DialogClose>` closes it.
 */
/** Required: an untitled dialog announces as nothing to a screen reader. */
title: string;
description?: React.ReactNode;
children?: React.ReactNode;
/** Right-aligned action row under the body. */
footer?: React.ReactNode;
className?: string;

dtsPropsFor.EmptyState:
/**
 * Three flavours, and the distinction matters: "you finished" is a reward,
 * "nothing matches" needs an escape hatch, "nothing yet" needs an explanation.
 */
icon?: React.ReactNode;
title: string;
body?: React.ReactNode;
/** Buttons/links, centred under the body. */
action?: React.ReactNode;
className?: string;

dtsPropsFor.Kbd:
/** The key hint itself, e.g. "i" or "⌘E". */
children?: React.ReactNode;
/** Colour is inherited via currentColor — never set a fixed text token here. */
className?: string;

dtsPropsFor.TriageCard:
/** The posting. These are the `JobView` fields this card reads. */
job: {
  company: string;
  title: string;
  url: string;
  /** Rendered as "Posted {posted}"; falls back to "Open posting" when null. */
  posted: string | null;
  industry: string | null;
  /** Verbatim from the board, never synthesized. null renders "Not listed". */
  compRange: string | null;
  minYoe: number | null;
  workModel: string | null;
  location: string | null;
  remote: boolean;
  roleFocus: string | null;
  skills: string[];
};
/** One line above Focus when the row conflicts with the search profile. */
mismatch?: string | null;

dtsPropsFor.CoverageMeter:
/**
 * The company universe. The meter describes the APPROVED subset only and
 * says so on screen — it filters `rows` itself.
 */
rows: Array<{
    key: string;
    id: number;
    /** "" for a slug-only row — Common Crawl mines boards, not names. */
    name: string;
    /** ATS family, or "" when unresolved: greenhouse | ashby | lever | … */
    ats: string;
    slug: string;
    /** How it was discovered: dork | commoncrawl | edgar | formadv | manual */
    source: string;
    /** 1 = day-of adapter · 2 = aggregator, lagged · 3 = manual · null = ungrounded */
    tier: 1 | 2 | 3 | null;
    /** Which waterfall step grounded it, e.g. "discover-greenhouse", "fingerprint". */
    resolutionMethod: string;
    reviewState: "proposed" | "approved" | "dismissed";
    enabled: boolean;
    priority: boolean;
    seeded: boolean;
    linkedinCompanyId: string;
    updatedAt: string | null;
    companyUpdatedAt: string | null;
  }>;

dtsPropsFor.ProvenanceChip:
