onUndo?: () => void;
onApprove: () => void;
onDismiss: () => void;
onClear: () => void;

dtsPropsFor.SelectionBar:
/** Fixed to the viewport, visible only while rows are selected. */
count: number;
busy: boolean;
onInterested: () => void;
onSnooze: () => void;
onDismiss: () => void;
onCopy: () => void;
onClear: () => void;
