exportMenu: React.ReactNode;

dtsPropsFor.StatusSelect:
applicationId: number;
/** The current status. Any string — a human-invented one ranks highest. */
status: string;
disabled?: boolean;
/** Called with the chosen status; a custom one arrives here once typed. */
onSelect: (status: string) => void;

dtsPropsFor.StepHeader:
title: string;
/** The file this step belongs to, printed beside the step counter. */
filename: string;
/** 1-based, out of four — stated so a person knows how much is left. */
step: number;
detail?: React.ReactNode;
/** Controls aligned to the right of the title. */
actions?: React.ReactNode;

dtsPropsFor.PreviewPanel:
/**
 * What the search profile WOULD have let through. Never renders an
 * unresolved spinner: a preview that cannot be computed says so and offers
 * the save anyway.
 */
state:
  | { kind: "idle" }
  | { kind: "running" }
  | { kind: "failed"; message: string }
  | {
      /** "stale" = the settings moved since this was computed. */
      kind: "ready" | "stale";
      preview: {
        /** Postings in the window, before anything is judged. */
        corpusTotal: number;
        /** …of those, how many match the profile's title lists. */
        titleMatched: number;
        /** How many include-terms the profile carries. 0 is a distinct state. */
        titlesConfigured: number;
        qualified: number;
        filtered: number;
        needsInfo: number;
        /** reason KIND -> n, first-hit only. Not rendered. */
        reasonCounts: Record<string, number>;
        /** The single setting refusing the most postings, or null. */
        binding: {
          field: string;
          /** The /settings anchor id this deep-links to. */
          setting: string;
          label: string;
          /** Postings that qualify with this one field relaxed. */
          recovers: number;
          /** One posting this field is currently refusing, in English. */
          sample: string;
        } | null;
        samples: {
          qualified: Array<{
            key: string;
            company: string;
            title: string;
            metro: string | null;
            compRange: string | null;
            workModel: string | null;
            /** Raw disposition reason; "" for a qualified sample. */
            reason: string;
            /** The same thing in English. */
            explanation: string;
          }>;
          filtered: Array<{
            key: string;
            company: string;
            title: string;
            metro: string | null;
            compRange: string | null;
            workModel: string | null;
            reason: string;
            explanation: string;
          }>;
        };
        /** Clamped to 1–90 by the SQL, and rendered — so it is the clamped value. */
        windowDays: number;
        computedAt: string;
      };
    };
/** Focus + scroll the /settings section a binding constraint names. */
onGoToSetting: (setting: string) => void;
